package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen1Test {

    private static final byte[] TEST_DATA = "Hello World".getBytes();
    private static final int LARGE_SIZE = 1000;

    @Test
    public void testEncodeBase64_NullInput() {
        byte[] result = Base64.encodeBase64(null, false, false, 100);
        assertNull(result);
    }

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] empty = new byte[0];
        byte[] result = Base64.encodeBase64(empty, false, false, 100);
        assertEquals(0, result.length);
    }

    @Test
    public void testEncodeBase64_ExceedsMaxSize() {
        // A small input but setting maxResultSize to 1 should trigger the exception
        try {
            Base64.encodeBase64(TEST_DATA, false, false, 1);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Input array too big"));
        }
    }

    @Test
    public void testEncodeBase64_StandardEncoding() {
        // isChunked = false, urlSafe = false
        byte[] result = Base64.encodeBase64(TEST_DATA, false, false, LARGE_SIZE);
        String expected = "SGVsbG8gV29ybGQ=";
        assertEquals(expected, new String(result));
    }

    @Test
    public void testEncodeBase64_UrlSafeEncoding() {
        // isChunked = false, urlSafe = true
        // Use data that produces '+' or '/' in standard Base64
        byte[] urlSafeData = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) 0xbf}; 
        // Standard: +/+ or similar. URL Safe: -_
        byte[] result = Base64.encodeBase64(urlSafeData, false, true, LARGE_SIZE);
        String resultStr = new String(result);
        assertFalse("Result should not contain '+'", resultStr.contains("+"));
        assertFalse("Result should not contain '/'", resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_ChunkedEncoding() {
        // isChunked = true, urlSafe = false
        // Chunked encoding adds line breaks/separators
        byte[] result = Base64.encodeBase64(TEST_DATA, true, false, LARGE_SIZE);
        String resultStr = new String(result);
        // In chunked mode, the length includes separators
        assertTrue("Chunked encoding should be longer than standard", result.length > 11);
    }

    @Test
    public void testEncodeBase64_ChunkedUrlSafeEncoding() {
        // isChunked = true, urlSafe = true
        byte[] urlSafeData = new byte[]{(byte) 0xfb, (byte) 0xff, (byte) 0xbf};
        byte[] result = Base64.encodeBase64(urlSafeData, true, true, LARGE_SIZE);
        String resultStr = new String(result);
        assertFalse(resultStr.contains("+"));
        assertFalse(resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_MaxResultSizeExact() {
        // Test the boundary where len == maxResultSize
        // For "Hello World", standard base64 is 16 bytes
        byte[] result = Base64.encodeBase64(TEST_DATA, false, false, 16);
        assertNotNull(result);
    }
}
